extern f32 ground_height_at(Vec4 *);
extern void KillPart_r(FallingParticle *) __asm__("func_L00_002688A8");

/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/rendering/effects/00268900.c, FUN_L00_00268d48. */
void update_falling_effect_particle(FallingParticle *p)
{
    Vec4 step;
    Vec4 tmp1;
    Vec4 tmp2;
    Vec4 *vel = &p->vel;
    f32 ground = vel->f[3];
    s32 cell_x;
    s32 cell_y;

    if (p->pos.f[2] < ground || p->pos.f[0] < 0.0f || p->pos.f[1] < 0.0f
        || 512.0f < p->pos.f[0] || 512.0f < p->pos.f[1])
        goto die;

    cell_x = p->probe.f[0];
    cell_y = p->probe.f[1];
    FastVecAdd(&step, vel, &particle_drift);
    FastVecAdd(&p->probe, &p->probe, &step);
    FastVecAdd(&p->pos, &p->pos, &step);
    if (p->unk0A != 2) {
        if (cell_x != (s32)p->probe.f[0] || cell_y != (s32)p->probe.f[1]) {
            tmp1.q = p->probe.q;
            if (ground_height_at(&tmp1) < particle_min_ground) {
                ground = particle_min_ground;
            } else {
                tmp2.q = p->probe.q;
                ground = ground_height_at(&tmp2);
            }
            if (p->probe.f[2] < ground) {
                /* shared exit; retail has one call site for all kill paths */
            die:
                KillPart_r(p);
                return;
            }
        }
    }
    vel->f[2] -= (*(f32 *)&g_frame_time_sq) * 9.8f;
    vel->f[3] = ground + particle_clearance.value;
}
