extern int truncate_float_to_s32_r(float) __asm__("func_001FA898");
extern int scale_ticks(int);
extern unsigned char *part_type01_textures;

/* spawns a type-1 particle at a position, fading with alpha a1 */
void spawn_timed_effect_particle(char *pos, int a1) {
    unsigned char *p = create_part(1);
    if (p != 0) {
        *(float *)(pos + 8) = *(float *)(pos + 8) + 0.1f;
        qcopy(p + 0x10, pos);
        *(int *)(p + 4) = (a1 << 24) | 0x907070;
        p[9] = truncate_float_to_s32_r(2.0f) + 0x40;
        p[3] = 0x48;
        p[1] = 0;
        p[2] = part_type01_textures[0];
        *(float *)(p + 0xC) = 31500.002f;
        p[8] = 0xA0;
        *(short *)(p + 0xA) = scale_ticks(0x1B);
        *(int *)(p + 0x20) = a1;
    }
}
extern int FastDecTimer(void *);
extern void KillPart(void *);

/* Particle update: fade alpha and step the texture frame over the lifetime; kill at timer end. */
void update_timed_effect_particle(char *m) {
    int t = *(short *)(m + 0xA) * *(int *)(m + 0x20) / scale_ticks(0x1B);
    int a;
    *(int *)(m + 4) = (*(int *)(m + 4) & 0xFFFFFF) | (t << 24);
    if (FastDecTimer(m + 0xA)) {
        KillPart(m);
    } else {
        a = scale_ticks(0x1B);
        m[2] = part_type01_textures[(a - *(short *)(m + 0xA)) * 9 / scale_ticks(0x1B)];
    }
}
